def _encode_chunked(s):
    if not s:
        return "0\r\n\r\n"
    try:
        chunk_len = len(s.encode("utf-8"))
        chunk_size = format(chunk_len, "x")
    except Exception:
        chunk_size = format(len(s), "x")
    return f"{chunk_size}\r\n{s}\r\n0\r\n\r\n"

def _decode_chunked(s):
    out = ""
    idx = 0
    while True:
        rn = s.find("\r\n", idx)
        if rn == -1:
            return None
        size_str = s[idx:rn]
        size_core = size_str.split(";")[0].strip()
        try:
            chunk_size = int(size_core, 16)
        except Exception:
            return None
        idx = rn + 2
        if chunk_size == 0:
            if s[idx:idx+2] == "\r\n":
                return out
            else:
                return None
        if idx + chunk_size > len(s):
            return None
        chunk = s[idx : idx + chunk_size]
        if len(chunk.encode("utf-8")) != chunk_size:
            return None
        out += chunk
        idx += chunk_size
        if s[idx:idx+2] != "\r\n":
            return None
        idx += 2
        while s[idx:idx+2] == "\r\n":
            idx += 2

def encode(input):
    return _encode_chunked(input)

def decode(input):
    return _decode_chunked(input)

class ChunkedCodingConverter:
    @staticmethod
    def encode(input):
        return encode(input)

    @staticmethod
    def decode(input):
        return decode(input)

